from collections import defaultdict, Counter

def clean_composer_string(c_str):
    return [c.strip() for c in c_str.split(',')]

def generate():
    with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Variables for KPIs
    all_composers = []
    seen_composers = set()
    repeat_ceremonies = 0
    unique_films = set()
    global_seen = set()

    # Track decade stats
    decade_stats = defaultdict(lambda: {'ceremonies': 0, 'repeat_ceremonies': 0, 'composers_this_decade': set(), 'wins': 0})

    # Track top composers
    composer_counts = Counter()
    composer_films = defaultdict(list)

    # Milestones
    first_time_winners = []
    longest_gap = 0
    longest_gap_composer = ""
    longest_gap_years = ()
    composer_win_years = defaultdict(list)

    for r in rows:
        y = int(r['Year'])
        f = r['Film']
        unique_films.add(f)
        comps = clean_composer_string(r['Composer'])

        d = (y // 10) * 10
        decade_stats[d]['ceremonies'] += 1

        is_repeat_ceremony = False

        for c in comps:
            all_composers.append(c)
            composer_counts[c] += 1
            composer_films[c].append(f"{f} ({y})")
            decade_stats[d]['composers_this_decade'].add(c)
            decade_stats[d]['wins'] += 1
            composer_win_years[c].append(y)

            if c in global_seen:
                is_repeat_ceremony = True
            else:
                first_time_winners.append({'year': y, 'composer': c, 'film': f})

        for c in comps:
            global_seen.add(c)

        if is_repeat_ceremony:
            repeat_ceremonies += 1
            decade_stats[d]['repeat_ceremonies'] += 1

    total_ceremonies = len(rows)
    total_unique_composers = len(global_seen)
    max_wins = max(composer_counts.values())
    repeat_winner_rate = (repeat_ceremonies / total_ceremonies) * 100

    # Decade with most unique winners
    max_unique_in_decade = max(len(s['composers_this_decade']) for s in decade_stats.values())
    most_unique_decades = [str(d)+"s" for d, s in decade_stats.items() if len(s['composers_this_decade']) == max_unique_in_decade]
    most_unique_decade_str = " & ".join(most_unique_decades)

    # Longest gap
    for c, years in composer_win_years.items():
        if len(years) > 1:
            years.sort()
            for i in range(1, len(years)):
                gap = years[i] - years[i-1]
                if gap > longest_gap:
                    longest_gap = gap
                    longest_gap_composer = c
